/**
 * Turbo Streams Custom Element & Protocol Handler
 * Local distribution for SPP Framework Real-Time Orchestration
 */
(function(global) {
    'use strict';

    class TurboStreamElement extends HTMLElement {
        connectedCallback() {
            try {
                this.performAction();
            } catch (error) {
                console.error("TurboStreamActionError:", error, this);
            }
        }

        performAction() {
            const action = this.getAttribute("action");
            const targetId = this.getAttribute("target");
            const targetsQuery = this.getAttribute("targets");
            
            let targets = [];
            if (targetId) {
                const element = document.getElementById(targetId);
                if (element) targets.push(element);
            } else if (targetsQuery) {
                targets = Array.from(document.querySelectorAll(targetsQuery));
            }

            if (targets.length === 0 && action !== "append" && action !== "prepend") {
                return;
            }

            const template = this.querySelector("template");
            const content = template ? template.content : null;

            targets.forEach(target => {
                switch (action) {
                    case "append":
                        if (content) target.appendChild(content.cloneNode(true));
                        break;
                    case "prepend":
                        if (content) target.insertBefore(content.cloneNode(true), target.firstChild);
                        break;
                    case "replace":
                        if (content) target.replaceWith(content.cloneNode(true));
                        break;
                    case "update":
                        if (content) {
                            target.innerHTML = "";
                            target.appendChild(content.cloneNode(true));
                        }
                        break;
                    case "remove":
                        target.remove();
                        break;
                    case "before":
                        if (content) target.parentNode.insertBefore(content.cloneNode(true), target);
                        break;
                    case "after":
                        if (content) target.parentNode.insertBefore(content.cloneNode(true), target.nextSibling);
                        break;
                    default:
                        console.warn(`Unsupported turbo-stream action: ${action}`);
                }
            });

            // Re-initialize HTMX bindings on newly inserted elements if HTMX is available
            if (typeof window.htmx !== 'undefined' && window.htmx.process) {
                window.htmx.process(document.body);
            }

            // Remove the stream element itself from DOM once executed
            this.remove();
        }
    }

    if (typeof window !== 'undefined' && window.customElements && !window.customElements.get("turbo-stream")) {
        window.customElements.define("turbo-stream", TurboStreamElement);
    }

    global.TurboStreams = {
        version: "1.0.0",
        register: function() {
            console.log("SPP Turbo Streams initialized.");
        }
    };
})(this);
